<?php use SwimlogStandalone\WorkoutEntry as WE;$f=$entryForm;$v=array_map(static function($value){return is_string($value)?$value:'';},$f['values']); ?>
<section class="calendar-panel workout-page" aria-labelledby="entry-title"><div class="workout-page-heading"><h2 id="entry-title">Add Workout</h2><a class="control" href="/?screen=log">Workout Log</a></div>
<p>Record a completed pool swim in meters or yards. Totals are enough; sets are optional. Leave start time blank to store noon on your selected local date.</p>
<?php $error=$entryError?:$f['error'];if($error): ?><p role="alert"><?php echo esc_html($error->get_error_message()); ?></p><?php endif; ?>
<form method="post" action="/?action=manual_save" class="manual-entry plan-editor" data-manual-entry>
<input type="hidden" name="token" value="<?php echo esc_attr($f['token']); ?>"><input type="hidden" name="nonce" value="<?php echo esc_attr(wp_create_nonce('standalone_entry_manual_'.$f['token'])); ?>">
<?php foreach(array('workout_date'=>array('Workout date','date'),'workout_time'=>array('Start time (optional)','time'),'pool_length'=>array('Pool length','number'),'total_distance'=>array('Total distance (pool unit)','number'),'duration'=>array('Workout duration (optional)','text'))as$key=>$field): ?><div class="plan-field"><label for="entry-<?php echo esc_attr($key); ?>"><?php echo esc_html($field[0]); ?></label><input id="entry-<?php echo esc_attr($key); ?>" name="<?php echo esc_attr($key); ?>" type="<?php echo esc_attr($field[1]); ?>" value="<?php echo esc_attr(is_string($v[$key]??null)?$v[$key]:''); ?>" <?php if(in_array($key,array('workout_date','pool_length'),true))echo 'required'; ?> <?php if($field[1]==='number')echo 'min="0" step="0.001"'; ?> <?php if($key==='workout_date')echo 'min="1900-01-01" max="2199-12-31"'; ?> maxlength="100"><?php if($key==='duration'): ?><small>Seconds, M:SS or H:MM:SS; up to three fractional-second digits.</small><?php endif; ?></div><?php endforeach; ?>
<div class="plan-field"><label for="entry-course">Pool and distance unit</label><select id="entry-course" name="course_unit"><?php foreach(array('m'=>'Meters','yd'=>'Yards')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($v['course_unit']??'m',$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div>
<div class="plan-field"><label for="entry-location">Location</label><select id="entry-location" name="location_id"><option value="0">No location</option><?php foreach($entryLocations as$loc): ?><option value="<?php echo esc_attr($loc['id']); ?>" <?php selected($v['location_id']??'0',(string)$loc['id']); ?>><?php echo esc_html($loc['name']); ?></option><?php endforeach; ?></select></div>
<div class="plan-field plan-wide"><label for="entry-notes">Workout notes (optional)</label><textarea id="entry-notes" name="notes" rows="4" maxlength="6000"><?php echo esc_textarea(is_string($v['notes']??null)?$v['notes']:''); ?></textarea></div>
<details class="plan-wide manual-sets" <?php if($f['error'])echo 'open'; ?>><summary>Workout sets (optional)</summary><p>Only explicitly measured repetition times can qualify for personal bests. Set totals and send-offs are not divided into invented repetition times. Choose the timing mode that describes what you measured; inactive timing fields are retained on screen but are not saved.</p>
<div data-set-list><?php $rows=is_array($f['sets'])?$f['sets']:array(WE::blankSet());foreach(array_slice(array_values($rows),0,100)as$i=>$row):$row=is_array($row)?array_map(static function($value){return is_string($value)?$value:'';},$row):WE::blankSet();$row=array_merge(WE::blankSet(),$row);require __DIR__.'/manual-set.php';endforeach; ?></div>
<button type="button" class="control" data-add-set>Add set</button><noscript><p>Enable JavaScript to add, remove or reorder multiple sets.</p></noscript></details>
<input type="hidden" name="payload_complete" value="1"><div class="plan-actions plan-wide"><button>Save workout</button><a class="control" href="/?screen=log">Cancel</a></div></form>
<template id="manual-set-template"><?php $i=0;$row=WE::blankSet();require __DIR__.'/manual-set.php'; ?></template><script src="/assets/manual-entry.js" defer></script></section>
